import { mkdirSync, writeFileSync } from 'node:fs';
import { getBrowser } from './browser.js';
import { setSystemFields, getById } from '../db/bookmarks.repo.js';

const PRESERVE_DIR = process.env.PRESERVE_DIR || 'data/preserved';

function ensureDir() {
  mkdirSync(PRESERVE_DIR, { recursive: true });
}

// Detect whether the URL resolves to a PDF (Content-Type or extension confirmed
// by the response), returning { isPdf, buffer? }.
async function probe(url) {
  try {
    const res = await fetch(url, {
      redirect: 'follow',
      signal: AbortSignal.timeout(15_000),
      headers: { 'User-Agent': 'BookmarkManager/1.0' },
    });
    const ct = (res.headers.get('content-type') || '').toLowerCase();
    if (ct.includes('application/pdf')) {
      const buffer = Buffer.from(await res.arrayBuffer());
      return { isPdf: true, buffer };
    }
    return { isPdf: false };
  } catch {
    return { isPdf: false };
  }
}

// Produce a single self-contained HTML string by inlining same-origin (and any
// CORS-permitted) stylesheets and images as <style>/data URIs. Best-effort.
async function snapshotHtml(url) {
  const browser = await getBrowser();
  const context = await browser.newContext({ userAgent: 'BookmarkManager/1.0' });
  try {
    const page = await context.newPage();
    await page.goto(url, { waitUntil: 'networkidle', timeout: 20_000 }).catch(async () => {
      await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 20_000 });
    });

    await page.evaluate(async () => {
      // Inline external stylesheets.
      const links = Array.from(document.querySelectorAll('link[rel~="stylesheet"][href]'));
      for (const link of links) {
        try {
          const css = await (await fetch(link.href)).text();
          const style = document.createElement('style');
          style.textContent = css;
          link.replaceWith(style);
        } catch { /* leave the link if it cannot be fetched */ }
      }
      // Inline images as data URIs.
      const toDataUrl = (blob) => new Promise((resolve, reject) => {
        const fr = new FileReader();
        fr.onload = () => resolve(fr.result);
        fr.onerror = reject;
        fr.readAsDataURL(blob);
      });
      const imgs = Array.from(document.querySelectorAll('img[src]'));
      for (const img of imgs) {
        try {
          const blob = await (await fetch(img.src)).blob();
          img.setAttribute('src', await toDataUrl(blob));
          img.removeAttribute('srcset');
        } catch { /* leave the original src */ }
      }
    });

    const html = await page.content();
    return `<!-- Preserved by Bookmark Manager from ${url} -->\n${html}`;
  } finally {
    await context.close().catch(() => {});
  }
}

// Preserve a local copy: original PDF for a PDF link, else a self-contained HTML
// file. Best-effort; never throws; sets preserved_status (FR-026/FR-027/FR-029).
export async function preserveLocal(bookmarkId, url) {
  if (!getById(bookmarkId)) return;
  setSystemFields(bookmarkId, { preserved_status: 'pending' });
  ensureDir();
  try {
    const { isPdf, buffer } = await probe(url);
    if (isPdf) {
      const path = `${PRESERVE_DIR}/${bookmarkId}.pdf`;
      writeFileSync(path, buffer);
      setSystemFields(bookmarkId, {
        preserved_path: path,
        preserved_kind: 'pdf',
        preserved_status: 'ready',
      });
    } else {
      const html = await snapshotHtml(url);
      const path = `${PRESERVE_DIR}/${bookmarkId}.html`;
      writeFileSync(path, html, 'utf8');
      setSystemFields(bookmarkId, {
        preserved_path: path,
        preserved_kind: 'html',
        preserved_status: 'ready',
      });
    }
  } catch {
    if (getById(bookmarkId)) setSystemFields(bookmarkId, { preserved_status: 'failed' });
  }
}

