:root {
  --bg: #f5f6f8;
  --panel: #ffffff;
  --border: #e2e5ea;
  --text: #1f2430;
  --muted: #6b7280;
  --accent: #2563eb;
  --danger: #dc2626;
  --radius: 10px;
  --fs: 15px;
}
html[data-text-size="small"] { --fs: 13px; }
html[data-text-size="medium"] { --fs: 15px; }
html[data-text-size="large"] { --fs: 18px; }

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: var(--fs);
  color: var(--text);
  background: var(--bg);
}

.app-header {
  background: var(--panel);
  border-bottom: 1px solid var(--border);
  padding: 12px 20px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
}
.app-header h1 { font-size: 1.15em; margin: 0 16px 0 0; }
.add-form, .search-form { display: flex; gap: 8px; flex: 1; min-width: 280px; }
input, select, button, textarea { font-size: 1em; font-family: inherit; }
input[type="text"], input[type="search"], select, textarea {
  padding: 8px 10px; border: 1px solid var(--border); border-radius: 8px; background: #fff; color: var(--text);
}
.add-form #add-url { flex: 2; }
.add-form #add-title { flex: 1; }
.search-form #search-input { flex: 1; }
button {
  padding: 8px 12px; border: 1px solid var(--border); border-radius: 8px;
  background: #fff; cursor: pointer; color: var(--text);
}
button:hover { background: #f0f2f5; }
.add-form button, .search-form button[type="submit"] { background: var(--accent); color: #fff; border-color: var(--accent); }
.add-form button:hover, .search-form button[type="submit"]:hover { filter: brightness(1.05); }
button.danger { color: var(--danger); border-color: #f3c7c7; }
.link-btn { display: block; width: 100%; text-align: left; border: none; background: none; padding: 6px 4px; color: var(--accent); }
.link-btn:hover { background: #eef2ff; border-radius: 6px; }

.app-body { display: flex; align-items: flex-start; }
.sidebar {
  width: 230px; flex-shrink: 0; padding: 16px; border-right: 1px solid var(--border);
  background: var(--panel); min-height: calc(100vh - 62px);
}
.sidebar h3 { font-size: 0.8em; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin: 18px 0 6px; }
.views { list-style: none; margin: 0; padding: 0; }
.views li { margin-bottom: 4px; }
.nav { width: 100%; text-align: left; border: none; background: none; padding: 8px 10px; border-radius: 8px; }
.nav:hover { background: #eef2ff; }
.nav.active { background: var(--accent); color: #fff; }
.tag-list, .saved-views { list-style: none; margin: 0; padding: 0; }
.tag-list li, .saved-views li { display: flex; justify-content: space-between; align-items: center; }
.tag-list button { border: none; background: none; padding: 5px 6px; width: 100%; text-align: left; border-radius: 6px; }
.tag-list button:hover { background: #eef2ff; }
.tag-list button.active { background: var(--accent); color: #fff; }
.tag-count { color: var(--muted); font-size: .85em; }
.saved-views .view-open { border: none; background: none; text-align: left; flex: 1; padding: 5px 6px; color: var(--accent); }
.saved-views .view-del { border: none; background: none; color: var(--muted); cursor: pointer; }

.content { flex: 1; padding: 16px 24px; }
.toolbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; gap: 12px; flex-wrap: wrap; }
.toolbar-left { display: flex; align-items: center; gap: 14px; }
.select-all { color: var(--muted); font-size: .9em; }
.result-summary { color: var(--muted); font-size: .9em; }

.bulk-bar { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; background: #eef2ff; padding: 10px 12px; border-radius: var(--radius); margin-bottom: 12px; }
.bulk-bar #bulk-tags { width: 160px; }

.list { display: flex; flex-direction: column; gap: 10px; }
.card {
  display: flex; gap: 12px; background: var(--panel); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 12px 14px;
}
.card.selected { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
.card .sel { padding-top: 3px; }
.card .icon { width: 32px; height: 32px; border-radius: 6px; object-fit: cover; background: #eef0f4; flex-shrink: 0; }
.card .main { flex: 1; min-width: 0; }
.card .title-row { display: flex; align-items: baseline; gap: 8px; }
.card .title { font-weight: 600; color: var(--text); text-decoration: none; word-break: break-word; }
.card .title:hover { color: var(--accent); text-decoration: underline; }
.card .badge { font-size: .72em; padding: 1px 7px; border-radius: 999px; background: #eef0f4; color: var(--muted); }
.card .badge.unread { background: #fef3c7; color: #92400e; }
.card .desc { color: var(--muted); margin: 4px 0; font-size: .92em; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.card .url { color: #94a0b8; font-size: .8em; word-break: break-all; }
.card .tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 6px; }
.card .tag { font-size: .75em; background: #eef2ff; color: var(--accent); padding: 1px 8px; border-radius: 999px; }
.card .preview { width: 120px; height: 68px; object-fit: cover; border-radius: 8px; flex-shrink: 0; background: #eef0f4; }
.card .actions { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.card .actions button { padding: 4px 8px; font-size: .82em; }
.status { font-size: .75em; color: var(--muted); margin-top: 4px; }
.status .ok { color: #059669; } .status .fail { color: var(--danger); } .status .pending { color: #b45309; }
.notes { margin-top: 8px; padding: 8px 10px; background: #fafbfc; border: 1px solid var(--border); border-radius: 8px; font-size: .9em; }
.notes :first-child { margin-top: 0; } .notes :last-child { margin-bottom: 0; }

.empty { text-align: center; color: var(--muted); padding: 60px 20px; }

.modal-backdrop { position: fixed; inset: 0; background: rgba(15,20,30,.45); display: flex; align-items: center; justify-content: center; z-index: 50; }
.modal { background: #fff; border-radius: var(--radius); padding: 20px; width: min(520px, 92vw); max-height: 88vh; overflow: auto; }
.modal h2 { margin-top: 0; }
.modal label { display: block; margin: 10px 0 4px; font-size: .9em; color: var(--muted); }
.modal input[type=text], .modal textarea, .modal select { width: 100%; }
.modal .row { display: flex; gap: 8px; justify-content: flex-end; margin-top: 16px; }
.tag-suggest { border: 1px solid var(--border); border-radius: 8px; margin-top: 2px; background: #fff; max-height: 140px; overflow: auto; }
.tag-suggest div { padding: 6px 10px; cursor: pointer; }
.tag-suggest div:hover { background: #eef2ff; }

.toast { position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%); background: #1f2430; color: #fff; padding: 10px 16px; border-radius: 8px; z-index: 60; }

