function updateBulkBar() {
  const bar = $('#bulk-bar');
  const n = state.selection.size;
  bar.hidden = n === 0;
  $('#bulk-count').textContent = `${n} selected`;
}

async function runBulk(action) {
  const ids = [...state.selection];
  if (!ids.length) return;
  const body = { selection: { ids }, action };
  if (action === 'addTags' || action === 'removeTags') {
    body.tags = parseTags($('#bulk-tags').value);
    if (!body.tags.length) { toast('Enter tags first.'); return; }
  }
  if (action === 'delete') {
    if (!confirm(`Permanently delete ${ids.length} bookmark(s)? This cannot be undone.`)) return;
    body.confirm = true;
  }
  const { ok, data } = await api('POST', '/api/bookmarks/bulk', body);
  if (ok) { toast(`Applied to ${data.affected} bookmark(s).`); state.selection.clear(); loadSidebar(); refresh(); }
}

